local mainFrame = LMG2L["Frame_2"]
local topBar = LMG2L["Frame_9"]
local minimizeButton = LMG2L["TextButton_10"]

local TweenService = game:GetService("TweenService")

local minimized = false
local normalSize = UDim2.new(0, 844, 0, 484)
local topBarHeight = 10

minimizeButton.MouseButton1Click:Connect(function()
	if not minimized then

		for _, obj in ipairs(mainFrame:GetChildren()) do
			if obj ~= topBar and obj:IsA("GuiObject") then
				obj.Visible = false
			end
		end

		local tween = TweenService:Create(
			mainFrame,
			TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
			{Size = UDim2.new(0, 844, 0, topBarHeight)}
		)
		tween:Play()

		minimized = true

	else

		local tween = TweenService:Create(
			mainFrame,
			TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
			{Size = normalSize}
		)
		tween:Play()

		tween.Completed:Wait()

		for _, obj in ipairs(mainFrame:GetChildren()) do
			if obj:IsA("GuiObject") then
				obj.Visible = true
			end
		end

		minimized = false
	end
end)

